import com.vanigam.clothing.*;import org.json.*;import java.io.*;import java.util.*;
public class CoreChecks{
 static int n;static JSONObject s;static String admin,staff,pid;
 static void ok(boolean b,String why)throws Exception{if(!b)throw new Exception(why);n++;}
 interface Task{void run()throws Exception;}static void reject(Task f,String why)throws Exception{try{f.run();}catch(Exception e){n++;return;}throw new Exception("Expected rejection: "+why);}
 static JSONObject mutate(String type,JSONObject args,String user)throws Exception{JSONObject copy=new JSONObject(s.toString());JSONObject r=Core.act(copy,type,args,user);copy.put("version",copy.getLong("version")+1);s=copy;return r;}
 static JSONObject product(String code,long price,long cost,long qty)throws Exception{return Core.obj("sku",code,"name","பருத்தி சட்டை","size","M","colour","Navy","price",price,"cost",cost,"qty",qty,"alert",3,"active",true);}
 static JSONObject request(int qty,String mobile,long redeem,long received,long upi,long card)throws Exception{return Core.obj("key",Core.id(),"lines",new JSONArray().put(Core.obj("id",pid,"qty",qty)),"discount",0,"redeem",redeem,"mobile",mobile,"customerName","சிவா","received",received,"upi",upi,"card",card);}
 public static void main(String[]args)throws Exception{
  s=Core.seed();JSONObject owner=mutate("setup",Core.obj("name","Siva","shop","Siva Clothing","pin","1234"),"");admin=owner.getString("uid");ok(Core.login(s,"1234").equals(admin),"PIN identifies user");reject(()->Core.login(s,"1111"),"bad PIN");reject(()->mutate("setup",Core.obj(),""),"setup only once");
  mutate("user",Core.obj("name","Cashier","pin","5678","admin",false),admin);staff=Core.login(s,"5678");reject(()->mutate("user",Core.obj("name","Duplicate","pin","5678"),admin),"duplicate PIN");reject(()->mutate("user",Core.obj("name","Other","pin","9999"),staff),"staff cannot create user");
  mutate("product",product("SH001",10000,6000,500),admin);pid=s.getJSONArray("products").getJSONObject(0).getString("id");ok(s.getJSONArray("movements").length()==1,"opening movement");reject(()->mutate("product",product("SH001",10000,0,1),admin),"unique code");reject(()->mutate("product",product("SH002",10000,0,1),staff),"admin product permission");
  JSONObject req=request(100,"9876543210",0,500000,300000,200000);JSONObject paid=mutate("checkout",req,staff).getJSONObject("bill");ok(paid.getLong("total")==1000000&&paid.getLong("earned")==100,"100 rupees per point");ok(s.getJSONArray("customers").getJSONObject(0).getLong("points")==100,"customer earned balance");ok(s.getJSONArray("products").getJSONObject(0).getLong("stock")==400,"stock decremented");ok(paid.getString("cashier").equals("Cashier"),"cashier snapshot");mutate("checkout",req,staff);ok(s.getJSONArray("bills").length()==1&&s.getJSONArray("points").length()==1,"idempotent retry no duplicate sale or points");
  JSONObject use=request(2,"9876543210",100,15000,0,0);JSONObject b=mutate("checkout",use,staff).getJSONObject("bill");ok(b.getLong("reward")==10000&&b.getLong("total")==10000,"100 points worth 100 rupees");ok(b.getLong("change")==5000&&b.getLong("cash")==10000,"instant cash change calculation");ok(s.getJSONArray("customers").getJSONObject(0).getLong("points")==1,"redemption consumes points and earns on paid amount");
  String before=s.toString();reject(()->mutate("checkout",request(1,"9876543210",1,9900,0,0),staff),"below 100 balance cannot redeem");ok(s.toString().equals(before),"failed transaction leaves complete state intact");reject(()->mutate("checkout",request(1000,"",0,10000000,0,0),staff),"overselling");reject(()->mutate("checkout",request(1,"",0,10000,10000,0),staff),"digital full amount with extra cash");reject(()->mutate("checkout",request(1,"",0,0,5000,0),staff),"insufficient payment");reject(()->mutate("checkout",request(1,"123",0,10000,0,0),staff),"invalid mobile");
  mutate("opening",Core.obj("amount",50000),staff);reject(()->mutate("opening",Core.obj("amount",60000),staff),"duplicate opening");mutate("expense",Core.obj("amount",10000,"method","Cash","note","Packing supplies"),admin);reject(()->mutate("expense",Core.obj("amount",10000,"method","Cash","note","x"),staff),"expense admin gate");
  mutate("stock",Core.obj("id",pid,"qty",2,"cost",10000,"type","Purchase","note","INV-1"),admin);ok(s.getJSONArray("products").getJSONObject(0).getLong("cost")==6020,"weighted average cost");mutate("stock",Core.obj("id",pid,"qty",1,"cost",0,"type","Wastage","note","Damaged"),admin);reject(()->mutate("stock",Core.obj("id",pid,"qty",10000,"cost",0,"type","Wastage","note","bad"),admin),"negative stock prevented");
  JSONObject policy=new JSONObject(s.getJSONObject("settings").toString());policy.put("taxRate",5).put("earnSpend",5000).put("pointValue",200).put("minimumPoints",100);mutate("settings",policy,admin);JSONObject taxed=mutate("checkout",request(1,"9876543210",0,10000,0,0),admin).getJSONObject("bill");ok(taxed.getLong("tax")==476&&taxed.getLong("earned")==2,"inclusive tax and configurable earn rule");ok(paid.getJSONObject("shop").getLong("earnSpend")==10000,"paid invoice settings snapshot");
  JSONObject safe=Core.safe(s,staff);ok(safe.getJSONArray("bills").length()==2,"staff sees own collections");ok(!safe.getJSONArray("users").getJSONObject(0).has("hash")&&!safe.getJSONObject("me").has("salt"),"no credential hashes in UI");Core.validateBackup(s);ok(true,"restore schema and stock/bill validation");JSONObject corrupt=new JSONObject(s.toString());corrupt.getJSONArray("products").getJSONObject(0).put("stock",999);reject(()->Core.validateBackup(corrupt),"corrupt stock backup rejected");
  for(String type:new String[]{"bills","dashboard","products","stock","stockreport","collection","opening","top","pl","customers","backup"}){List<Excel.Sheet> sheets=Excel.report(s,type,"0000-01-01","9999-12-31");ok(!sheets.isEmpty(),"export "+type);}
  List<Excel.Sheet> pl=Excel.report(s,"pl","0000-01-01","9999-12-31");ok(((Double)pl.get(0).rows.get(6)[1])==3854.84,"P&L sales less included tax, snapshot cost, expense and waste");
  new File("mobile/test-output").mkdirs();try(FileOutputStream out=new FileOutputStream("mobile/test-output/backup.xlsx")){Excel.write(out,Excel.report(s,"backup","0000-01-01","9999-12-31"));}try(FileOutputStream out=new FileOutputStream("mobile/test-output/state.json")){out.write(Core.safe(s,admin).toString().getBytes("UTF-8"));}
  ok(Core.money("250.50")==25050,"paise conversion");reject(()->Core.money("1.001"),"fractional paise blocked");reject(()->Core.money("-1"),"negative amounts blocked");System.out.println("PASS "+n+" core/auth/stock/payment/points/report/backup checks");
 }
}
